import { Metadata } from "next"

import Dashboard from "@/components/templates/dashboard/dashboard"

export const metadata: Metadata = {
  title: "Tally - Store dashboard",
  description:
    "Revenue, orders, customers, marketing and inventory at a glance.",
}

export default function Page() {
  return <Dashboard />
}

"use client"

import { Download } from "lucide-react"

import {
  useEffect,
  useMemo,
  useState,
  type ComponentType,
  type CSSProperties,
} from "react"

import { Button } from "@/components/ui/button"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
} from "@/components/ui/sidebar"

import AppSidebar from "./app-sidebar"
import Billing from "./billing"
import Customers from "./customers"
import {
  downloadCsv,
  getPeriod,
  ordersOf,
  RANGES,
  revenueOf,
  sessionsOf,
  type Period,
} from "./data"
import Inventory from "./inventory"
import Marketing from "./marketing"
import Orders from "./orders"
import Overview from "./overview"
import Profile from "./profile"
import Revenue from "./revenue"

const PAGES: Record<
  string,
  {
    title: string
    component: ComponentType<{ period: Period }>
    // Account pages have no date range or export.
    account?: boolean
  }
> = {
  overview: { title: "Overview", component: Overview },
  revenue: { title: "Revenue", component: Revenue },
  marketing: { title: "Marketing", component: Marketing },
  orders: { title: "Orders", component: Orders },
  customers: { title: "Customers", component: Customers },
  inventory: { title: "Inventory", component: Inventory },
  profile: { title: "Profile", component: Profile, account: true },
  billing: { title: "Billing", component: Billing, account: true },
}

// The open page lives in the URL hash, so the back button and shared links
// work while everything stays on one route.
function useHashPage() {
  const [page, setPage] = useState("overview")

  useEffect(() => {
    const read = () => {
      const hash = window.location.hash.slice(1)
      setPage(hash in PAGES ? hash : "overview")
      window.scrollTo({ top: 0, behavior: "instant" })
    }
    read()
    window.addEventListener("hashchange", read)
    return () => window.removeEventListener("hashchange", read)
  }, [])

  return page
}

function exportCsv(period: Period) {
  downloadCsv("tally-report.csv", [
    ["date", "revenue", "orders", "refunds", "new_customers", "sessions"],
    ...period.days.map((day) => [
      day.date.toISOString().slice(0, 10),
      revenueOf(day),
      ordersOf(day),
      day.refunds,
      day.newCustomers,
      sessionsOf(day),
    ]),
  ])
}

export default function Dashboard() {
  const page = useHashPage()
  const [range, setRange] = useState("28")
  const period = useMemo(() => getPeriod(Number(range)), [range])
  const { title, component: Page, account } = PAGES[page]

  return (
    <SidebarProvider
      className="font-base text-foreground"
      // Collapsed, the sidebar is as wide as the header is tall (h-16).
      style={{ "--sidebar-width-icon": "4rem" } as CSSProperties}
    >
      <AppSidebar active={page} />
      <SidebarInset className="min-w-0 bg-background">
        <header className="sticky top-0 z-10 flex h-16 shrink-0 items-center gap-2 border-b-2 border-border bg-secondary-background px-4 sm:gap-3 sm:px-6">
          <SidebarTrigger className="size-9 shrink-0" />
          <h1 className="truncate font-heading text-lg sm:text-xl">{title}</h1>
          {!account && (
            <div className="ml-auto flex items-center gap-2 sm:gap-3">
              <Select
                items={RANGES}
                value={range}
                onValueChange={(value) => setRange(value ?? "28")}
              >
                <SelectTrigger
                  aria-label="Date range"
                  className="h-9 w-37 bg-secondary-background"
                >
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectGroup>
                    {RANGES.map((item) => (
                      <SelectItem key={item.value} value={item.value}>
                        {item.label}
                      </SelectItem>
                    ))}
                  </SelectGroup>
                </SelectContent>
              </Select>
              <Button
                size="sm"
                variant="noShadow"
                aria-label="Export CSV"
                onClick={() => exportCsv(period)}
              >
                <span className="hidden sm:inline">Export</span>
                <Download />
              </Button>
            </div>
          )}
        </header>
        <div className="flex flex-col gap-5 p-4 pb-28 sm:p-6 sm:pb-28">
          <Page period={period} />
        </div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import { Button } from "@/components/ui/button"

import { Comparison, Donut, RankedBars } from "./charts"
import {
  CHANNELS,
  formatCompactMoney,
  formatMoney,
  formatNumber,
  formatPercent,
  ORDERS,
  ordersOf,
  PRODUCTS,
  revenueOf,
  sessionsOf,
  total,
  type Day,
  type Period,
} from "./data"
import { OrderTable } from "./order-table"
import { CHANNEL_CONFIG } from "./revenue"
import { ChartCard, StatCard, StatGrid } from "./shared"

const revenueIn = (days: Day[]) => total(days, revenueOf)
const ordersIn = (days: Day[]) => total(days, ordersOf)
const averageIn = (days: Day[]) => revenueIn(days) / ordersIn(days)
const conversionIn = (days: Day[]) =>
  (total(days, (day) => day.orders.online) / total(days, sessionsOf)) * 100

export default function Overview({ period }: { period: Period }) {
  const { days, previous, buckets, previousBuckets, unit } = period
  const stat = (measure: (days: Day[]) => number) => ({
    compare: { current: measure(days), previous: measure(previous) },
    trend: buckets.map((item) => measure(item.days)),
  })

  return (
    <>
      <StatGrid>
        <StatCard
          label="Revenue"
          value={formatMoney(revenueIn(days))}
          {...stat(revenueIn)}
        />
        <StatCard
          label="Orders"
          value={formatNumber(ordersIn(days))}
          color="var(--chart-3)"
          {...stat(ordersIn)}
        />
        <StatCard
          label="Average order"
          value={`$${averageIn(days).toFixed(2)}`}
          color="var(--chart-4)"
          {...stat(averageIn)}
        />
        <StatCard
          label="Online conversion"
          value={formatPercent(conversionIn(days))}
          color="var(--chart-5)"
          {...stat(conversionIn)}
        />
      </StatGrid>

      <div className="grid gap-5 xl:grid-cols-3">
        <ChartCard
          title="Revenue trend"
          description={`Per ${unit}, against the previous period`}
          className="xl:col-span-2"
        >
          <Comparison
            className="h-80"
            format={formatMoney}
            axisFormat={formatCompactMoney}
            data={buckets.map((item, i) => ({
              label: item.label,
              current: revenueIn(item.days),
              previous: revenueIn(previousBuckets[i].days),
            }))}
          />
        </ChartCard>
        <ChartCard title="Sales channels" description="Share of revenue">
          <Donut
            caption="revenue"
            format={formatMoney}
            data={CHANNELS.map((key) => ({
              key,
              ...CHANNEL_CONFIG[key],
              value: total(days, (day) => day.revenue[key]),
            }))}
          />
        </ChartCard>
      </div>

      <div className="grid gap-5 xl:grid-cols-3">
        <ChartCard title="Top products" description="By revenue">
          <RankedBars
            label="Revenue"
            color="var(--chart-3)"
            format={formatMoney}
            data={PRODUCTS.slice(0, 6).map((product) => ({
              label: product.name,
              value: revenueIn(days) * product.share,
            }))}
          />
        </ChartCard>
        <ChartCard
          title="Recent orders"
          className="xl:col-span-2"
          action={
            <Button
              size="sm"
              variant="neutral"
              nativeButton={false}
              render={<a href="#orders" />}
            >
              View all
            </Button>
          }
        >
          <OrderTable orders={ORDERS.slice(0, 5)} />
        </ChartCard>
      </div>
    </>
  )
}

"use client"

import type { ChartConfig } from "@/components/ui/chart"

import { Columns, RankedBars, Trend } from "./charts"
import {
  CHANNELS,
  COUNTRIES,
  formatCompactMoney,
  formatMoney,
  formatPercent,
  ordersOf,
  revenueOf,
  total,
  type Day,
  type Period,
} from "./data"
import { ChartCard, StatCard, StatGrid } from "./shared"

export const CHANNEL_CONFIG = {
  online: { label: "Online store", color: "var(--chart-1)" },
  marketplace: { label: "Marketplace", color: "var(--chart-3)" },
  retail: { label: "Retail", color: "var(--chart-2)" },
} satisfies ChartConfig

const REFUND_CONFIG = {
  refunds: { label: "Refunds", color: "var(--chart-2)" },
} satisfies ChartConfig

const grossIn = (days: Day[]) => total(days, revenueOf)
const refundsIn = (days: Day[]) => total(days, (day) => day.refunds)
const netIn = (days: Day[]) => grossIn(days) - refundsIn(days)
const refundRateIn = (days: Day[]) => (refundsIn(days) / grossIn(days)) * 100

export default function Revenue({ period }: { period: Period }) {
  const { days, previous, buckets, unit } = period
  const stat = (measure: (days: Day[]) => number) => ({
    compare: { current: measure(days), previous: measure(previous) },
    trend: buckets.map((item) => measure(item.days)),
  })

  return (
    <>
      <StatGrid>
        <StatCard
          label="Gross revenue"
          value={formatMoney(grossIn(days))}
          {...stat(grossIn)}
        />
        <StatCard
          label="Net revenue"
          value={formatMoney(netIn(days))}
          color="var(--chart-4)"
          {...stat(netIn)}
        />
        <StatCard
          label="Refunds"
          value={formatMoney(refundsIn(days))}
          color="var(--chart-2)"
          invert
          {...stat(refundsIn)}
        />
        <StatCard
          label="Refund rate"
          value={formatPercent(refundRateIn(days))}
          color="var(--chart-3)"
          invert
          {...stat(refundRateIn)}
        />
      </StatGrid>

      <ChartCard
        title="Revenue by channel"
        description={`Gross revenue per ${unit}`}
      >
        <Columns
          stacked
          config={CHANNEL_CONFIG}
          format={formatMoney}
          axisFormat={formatCompactMoney}
          className="h-80"
          data={buckets.map((item) => ({
            label: item.label,
            ...Object.fromEntries(
              CHANNELS.map((key) => [
                key,
                total(item.days, (day) => day.revenue[key]),
              ]),
            ),
          }))}
        />
      </ChartCard>

      <div className="grid gap-5 lg:grid-cols-2 xl:grid-cols-3">
        <ChartCard title="Average order value" description={`Per ${unit}`}>
          <Trend
            label="Average order"
            color="var(--chart-4)"
            format={(value) => `$${value.toFixed(2)}`}
            axisFormat={formatCompactMoney}
            data={buckets.map((item) => ({
              label: item.label,
              value: grossIn(item.days) / total(item.days, ordersOf),
            }))}
          />
        </ChartCard>
        <ChartCard title="Refunds" description={`Amount per ${unit}`}>
          <Columns
            config={REFUND_CONFIG}
            format={formatMoney}
            axisFormat={formatCompactMoney}
            data={buckets.map((item) => ({
              label: item.label,
              refunds: refundsIn(item.days),
            }))}
          />
        </ChartCard>
        <ChartCard
          title="Revenue by country"
          description="Where orders ship to"
          className="lg:col-span-2 xl:col-span-1"
        >
          <RankedBars
            label="Revenue"
            color="var(--chart-5)"
            format={formatMoney}
            data={COUNTRIES.map((country) => ({
              label: country.name,
              value: grossIn(days) * country.share,
            }))}
          />
        </ChartCard>
      </div>
    </>
  )
}

"use client"

import { Badge } from "@/components/ui/badge"
import type { ChartConfig } from "@/components/ui/chart"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"

import { Columns, RankedBars, StackedArea } from "./charts"
import {
  CAMPAIGNS,
  formatCompactMoney,
  formatMoney,
  formatNumber,
  formatPercent,
  FUNNEL,
  sessionsOf,
  SOURCES,
  sum,
  total,
  type Day,
  type Period,
} from "./data"
import { ChartCard, StatCard, StatGrid } from "./shared"

const SOURCE_CONFIG = {
  organic: { label: "Organic", color: "var(--chart-1)" },
  paid: { label: "Paid", color: "var(--chart-3)" },
  social: { label: "Social", color: "var(--chart-2)" },
  email: { label: "Email", color: "var(--chart-4)" },
} satisfies ChartConfig

const CAMPAIGN_CONFIG = {
  spend: { label: "Spend", color: "var(--chart-2)" },
  revenue: { label: "Revenue", color: "var(--chart-4)" },
} satisfies ChartConfig

function campaignsIn(days: Day[]) {
  const online = total(days, (day) => day.revenue.online)
  return CAMPAIGNS.map((campaign) => ({
    name: campaign.name,
    channel: campaign.channel,
    spend: campaign.spend * days.length,
    revenue: Math.round(online * campaign.share),
  }))
}

const sessionsIn = (days: Day[]) => total(days, sessionsOf)
const ordersIn = (days: Day[]) => total(days, (day) => day.orders.online)
const conversionIn = (days: Day[]) => (ordersIn(days) / sessionsIn(days)) * 100
const attributedIn = (days: Day[]) =>
  sum(campaignsIn(days).map((campaign) => campaign.revenue))
const roasIn = (days: Day[]) =>
  attributedIn(days) / sum(campaignsIn(days).map((campaign) => campaign.spend))

export default function Marketing({ period }: { period: Period }) {
  const { days, previous, buckets, unit } = period
  const campaigns = campaignsIn(days)
  const stat = (measure: (days: Day[]) => number) => ({
    compare: { current: measure(days), previous: measure(previous) },
    trend: buckets.map((item) => measure(item.days)),
  })

  return (
    <>
      <StatGrid>
        <StatCard
          label="Sessions"
          value={formatNumber(sessionsIn(days))}
          {...stat(sessionsIn)}
        />
        <StatCard
          label="Conversion"
          value={formatPercent(conversionIn(days))}
          color="var(--chart-5)"
          {...stat(conversionIn)}
        />
        <StatCard
          label="Campaign revenue"
          value={formatMoney(attributedIn(days))}
          color="var(--chart-4)"
          {...stat(attributedIn)}
        />
        <StatCard
          label="Return on ad spend"
          value={`${roasIn(days).toFixed(2)}×`}
          color="var(--chart-3)"
          {...stat(roasIn)}
        />
      </StatGrid>

      <ChartCard
        title="Traffic sources"
        description={`Online store sessions per ${unit}`}
      >
        <StackedArea
          config={SOURCE_CONFIG}
          className="h-80"
          data={buckets.map((item) => ({
            label: item.label,
            ...Object.fromEntries(
              SOURCES.map((key) => [
                key,
                total(item.days, (day) => day.sessions[key]),
              ]),
            ),
          }))}
        />
      </ChartCard>

      <div className="grid gap-5 xl:grid-cols-2">
        <ChartCard title="Purchase funnel" description="Online store visitors">
          <RankedBars
            label="Visitors"
            color="var(--chart-5)"
            data={[
              ...FUNNEL.map((step) => ({
                label: step.label,
                value: Math.round(sessionsIn(days) * step.share),
              })),
              { label: "Ordered", value: ordersIn(days) },
            ]}
          />
        </ChartCard>
        <ChartCard title="Spend and revenue" description="By campaign">
          <Columns
            allLabels
            config={CAMPAIGN_CONFIG}
            format={formatMoney}
            axisFormat={formatCompactMoney}
            data={campaigns.map(({ name, spend, revenue }) => ({
              label: name,
              spend,
              revenue,
            }))}
          />
        </ChartCard>
      </div>

      <ChartCard title="Campaigns" description="Spend and attributed revenue">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Campaign</TableHead>
              <TableHead className="hidden sm:table-cell">Channel</TableHead>
              <TableHead className="text-right">Spend</TableHead>
              <TableHead className="text-right">Revenue</TableHead>
              <TableHead className="text-right">ROAS</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {campaigns.map((campaign) => (
              <TableRow key={campaign.name} className="bg-secondary-background">
                <TableCell className="py-3 font-heading">
                  {campaign.name}
                </TableCell>
                <TableCell className="hidden py-3 sm:table-cell">
                  <Badge variant="neutral">{campaign.channel}</Badge>
                </TableCell>
                <TableCell className="py-3 text-right tabular-nums">
                  {formatMoney(campaign.spend)}
                </TableCell>
                <TableCell className="py-3 text-right tabular-nums">
                  {formatMoney(campaign.revenue)}
                </TableCell>
                <TableCell className="py-3 text-right font-heading tabular-nums">
                  {(campaign.revenue / campaign.spend).toFixed(2)}×
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </ChartCard>
    </>
  )
}

"use client"

import { ChevronLeft, ChevronRight } from "lucide-react"

import { useState } from "react"

import { Button } from "@/components/ui/button"
import type { ChartConfig } from "@/components/ui/chart"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"

import { Columns, Donut } from "./charts"
import {
  DISPATCH,
  formatNumber,
  getOrderHeatmap,
  HOURS,
  ORDERS,
  ordersOf,
  split,
  STATUS_COLORS,
  STATUS_SHARE,
  STATUSES,
  total,
  type Channel,
  type Day,
  type Period,
} from "./data"
import { OrderTable } from "./order-table"
import { ChartCard, Heatmap, StatCard, StatGrid } from "./shared"

const VOLUME_CONFIG = {
  orders: { label: "Orders", color: "var(--chart-1)" },
} satisfies ChartConfig

const DISPATCH_CONFIG = {
  orders: { label: "Orders", color: "var(--chart-5)" },
} satisfies ChartConfig

const STATUS_FILTERS = [
  { value: "All", label: "All statuses" },
  ...STATUSES.map((status) => ({ value: status, label: status })),
]

const PAGE_SIZE = 8

function LatestOrders() {
  const [query, setQuery] = useState("")
  const [status, setStatus] = useState("All")
  const [page, setPage] = useState(0)

  const needle = query.trim().toLowerCase()
  const matching = ORDERS.filter(
    (order) =>
      (status === "All" || order.status === status) &&
      [order.id, order.customer, order.product].some((text) =>
        text.toLowerCase().includes(needle),
      ),
  )
  const pages = Math.max(1, Math.ceil(matching.length / PAGE_SIZE))
  const visible = matching.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE)

  return (
    <ChartCard
      title="Latest orders"
      description={`The ${ORDERS.length} most recent orders`}
    >
      <div className="mb-4 flex flex-col gap-3 sm:flex-row">
        <Input
          aria-label="Search orders"
          placeholder="Search orders"
          value={query}
          onChange={(event) => {
            setQuery(event.target.value)
            setPage(0)
          }}
          className="sm:max-w-xs"
        />
        <Select
          items={STATUS_FILTERS}
          value={status}
          onValueChange={(value) => {
            setStatus(value ?? "All")
            setPage(0)
          }}
        >
          <SelectTrigger aria-label="Filter by status" className="sm:w-44">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectGroup>
              {STATUS_FILTERS.map((item) => (
                <SelectItem key={item.value} value={item.value}>
                  {item.label}
                </SelectItem>
              ))}
            </SelectGroup>
          </SelectContent>
        </Select>
      </div>
      {visible.length > 0 ? (
        <OrderTable orders={visible} />
      ) : (
        <p className="rounded-base border-2 border-border p-8 text-center text-sm">
          No orders match these filters.
        </p>
      )}
      <div className="mt-4 flex items-center justify-between text-sm">
        <p aria-live="polite">
          {matching.length} {matching.length === 1 ? "order" : "orders"}, page{" "}
          {page + 1} of {pages}
        </p>
        <div className="flex gap-3">
          <Button
            size="icon-sm"
            variant="neutral"
            aria-label="Previous page"
            disabled={page === 0}
            onClick={() => setPage(page - 1)}
          >
            <ChevronLeft />
          </Button>
          <Button
            size="icon-sm"
            variant="neutral"
            aria-label="Next page"
            disabled={page + 1 >= pages}
            onClick={() => setPage(page + 1)}
          >
            <ChevronRight />
          </Button>
        </div>
      </div>
    </ChartCard>
  )
}

export default function Orders({ period }: { period: Period }) {
  const { days, previous, buckets, unit } = period
  const orders = total(days, ordersOf)
  const byStatus = split(
    orders,
    STATUSES.map((status) => STATUS_SHARE[status]),
  )
  const byDispatch = split(
    orders,
    DISPATCH.map((item) => item.share),
  )
  const heatmap = getOrderHeatmap(days)

  const stat = (pick: (day: Day) => number) => ({
    value: formatNumber(total(days, pick)),
    compare: { current: total(days, pick), previous: total(previous, pick) },
    trend: buckets.map((item) => total(item.days, pick)),
  })
  const channel = (key: Channel) => stat((day) => day.orders[key])

  return (
    <>
      <StatGrid>
        <StatCard
          label="All orders"
          color="var(--chart-4)"
          {...stat(ordersOf)}
        />
        <StatCard label="Online store" {...channel("online")} />
        <StatCard
          label="Marketplace"
          color="var(--chart-3)"
          {...channel("marketplace")}
        />
        <StatCard
          label="Retail"
          color="var(--chart-2)"
          {...channel("retail")}
        />
      </StatGrid>

      <div className="grid gap-5 xl:grid-cols-3">
        <ChartCard
          title="Order volume"
          description={`Orders per ${unit}`}
          className="xl:col-span-2"
        >
          <Columns
            config={VOLUME_CONFIG}
            className="h-80"
            data={buckets.map((item) => ({
              label: item.label,
              orders: total(item.days, ordersOf),
            }))}
          />
        </ChartCard>
        <ChartCard title="Order status" description="Orders in this period">
          <Donut
            caption="orders"
            data={STATUSES.map((status, i) => ({
              key: status,
              label: status,
              color: STATUS_COLORS[status],
              value: byStatus[i],
            }))}
          />
        </ChartCard>
      </div>

      <div className="grid gap-5 xl:grid-cols-3">
        <ChartCard
          title="When people buy"
          description="Orders by weekday and time of day"
          className="xl:col-span-2"
        >
          <Heatmap
            corner="Day"
            columns={HOURS.map((hour) => `${String(hour).padStart(2, "0")}h`)}
            rows={heatmap.map((row) => ({
              label: row.weekday,
              values: row.values,
            }))}
            max={Math.max(...heatmap.flatMap((row) => row.values))}
          />
        </ChartCard>
        <ChartCard title="Time to dispatch" description="Payment to pickup">
          <Columns
            config={DISPATCH_CONFIG}
            data={DISPATCH.map((item, i) => ({
              label: item.label,
              orders: byDispatch[i],
            }))}
          />
        </ChartCard>
      </div>

      <LatestOrders />
    </>
  )
}

"use client"

import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  ComposedChart,
  LabelList,
  Line,
